import { Dayjs } from 'dayjs';

export function getComparisonPresetValue(
  value: [Dayjs | null, Dayjs | null],
  over: 'period_over_period' | 'year_over_year' | 'month_over_month',
): [Dayjs | null, Dayjs | null] {
  switch (over) {
    case 'period_over_period': {
      let daysCount: number;
      if (value[0] && value[1]) {
        daysCount = value[1].diff(value[0], 'day') + 1;
      } else {
        daysCount = 1;
      }
      return [
        value[0] ? value[0].subtract(daysCount, 'day') : null,
        value[1] ? value[1].subtract(daysCount, 'day') : null,
      ];
    }
    case 'month_over_month':
      return [value[0] ? value[0].subtract(1, 'month') : null, value[1] ? value[1].subtract(1, 'month') : null];
    case 'year_over_year':
      return [value[0] ? value[0].subtract(1, 'year') : null, value[1] ? value[1].subtract(1, 'year') : null];
    default:
      return [null, null];
  }
}
